import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ColorType {
  RED = 'RED',
  GREEN = 'GREEN',
  VIOLET = 'VIOLET'
}

export interface GameResult {
  id: string;
  period: string;
  number: number;
  colors: ColorType[];
  timestamp: number;
}

export interface UserBet {
  amount: number;
  selection: ColorType | number;
  timestamp: number;
}

export interface UserState {
  balance: number;
  id: string;
  phone: string;
  referralCode: string;
  avatarUrl?: string;
}

export enum Tab {
  HOME = 'HOME',
  HISTORY = 'HISTORY',
  WALLET = 'WALLET',
  PROFILE = 'PROFILE',
  AI_GEN = 'AI_GEN'
}

export type ImageSize = '1K' | '2K' | '4K';

import React from 'react';

export const INITIAL_BALANCE = 10000;
export const ROUND_DURATION_SECONDS = 30;

export const COLOR_CONFIG = {
  RED: {
    bg: 'bg-red-600',
    shadow: 'shadow-red-500/50',
    label: 'Red',
    numbers: [0, 2, 4, 6, 8]
  },
  GREEN: {
    bg: 'bg-green-600',
    shadow: 'shadow-green-500/50',
    label: 'Green',
    numbers: [1, 3, 7, 9]
  },
  VIOLET: {
    bg: 'bg-purple-600',
    shadow: 'shadow-purple-500/50',
    label: 'Violet',
    numbers: [0, 5]
  }
};

export const COLORS_BY_NUMBER: Record<number, string[]> = {
  0: ['RED', 'VIOLET'],
  1: ['GREEN'],
  2: ['RED'],
  3: ['GREEN'],
  4: ['RED'],
  5: ['GREEN', 'VIOLET'],
  6: ['RED'],
  7: ['GREEN'],
  8: ['RED'],
  9: ['GREEN']
};

import { GoogleGenAI } from "@google/genai";
import { ImageSize } from "../types";

// Note: Using the provided API key from process.env.API_KEY
// For gemini-3-pro-image-preview, the user selection is checked in UI

export async function generateLuckAvatar(prompt: string, size: ImageSize): Promise<string | null> {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: `Generate a high-detail luck-themed avatar or shield: ${prompt}. Artistic style: Neon Cyberpunk.` }]
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1",
          imageSize: size
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("AI Generation Error:", error);
    return null;
  }
}

