import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType } from './types.ts';
import { INITIAL_BALANCE, ROUND_DURATION_SECONDS, COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AIGenerationView from './views/AIGenerationView.tsx';
import AuthModal from './components/AuthModal.tsx';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [user, setUser] = useState<UserState | null>(null);
  const [results, setResults] = useState<GameResult[]>([]);
  const [timeLeft, setTimeLeft] = useState(ROUND_DURATION_SECONDS);
  const [currentPeriod, setCurrentPeriod] = useState("20241027001");

  // Timer logic
  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          generateResult();
          return ROUND_DURATION_SECONDS;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [currentPeriod]);

  const generateResult = useCallback(() => {
    const num = Math.floor(Math.random() * 10);
    const newResult: GameResult = {
      id: Math.random().toString(36).substr(2, 9),
      period: currentPeriod,
      number: num,
      colors: COLORS_BY_NUMBER[num] as ColorType[],
      timestamp: Date.now()
    };

    setResults(prev => [newResult, ...prev].slice(0, 50));
    const nextPeriodNum = parseInt(currentPeriod) + 1;
    setCurrentPeriod(nextPeriodNum.toString());
  }, [currentPeriod]);

  const handleLogin = (phone: string) => {
    setUser({
      id: "928374",
      phone: phone,
      balance: INITIAL_BALANCE,
      referralCode: "NEO777",
    });
  };

  const updateBalance = (amount: number) => {
    if (user) {
      setUser({ ...user, balance: user.balance + amount });
    }
  };

  const updateAvatar = (url: string) => {
    if (user) {
      setUser({ ...user, avatarUrl: url });
    }
  };

  if (!user) {
    return <AuthModal onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-neutral-950 text-white flex justify-center selection:bg-purple-500/30">
      <div className="w-full max-w-md pb-20 relative">
        <header className="sticky top-0 z-40 bg-neutral-950/80 backdrop-blur-md px-4 py-4 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-purple-600 to-pink-600 flex items-center justify-center font-bold font-orbitron text-xs">N</div>
            <h1 className="text-xl font-bold font-orbitron tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-pink-500">NEONPREDICT</h1>
          </div>
          <div className="px-3 py-1 rounded-full glass-morphism border border-white/10 flex items-center gap-2">
            <span className="text-yellow-400 text-xs font-bold">🪙</span>
            <span className="text-sm font-medium">{user.balance.toLocaleString()}</span>
          </div>
        </header>

        <main className="p-4 overflow-y-auto">
          {activeTab === Tab.HOME && (
            <HomeView 
              timeLeft={timeLeft} 
              period={currentPeriod} 
              results={results}
              balance={user.balance}
              onBet={updateBalance}
            />
          )}
          {activeTab === Tab.HISTORY && (
            <HistoryView results={results} />
          )}
          {activeTab === Tab.AI_GEN && (
            <AIGenerationView onAvatarCreated={updateAvatar} />
          )}
          {activeTab === Tab.WALLET && (
            <WalletView balance={user.balance} onDeposit={() => updateBalance(1000)} />
          )}
          {activeTab === Tab.PROFILE && (
            <ProfileView user={user} />
          )}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
    </div>
  );
};

export default App;

