export enum ColorType {
  RED = 'RED',
  GREEN = 'GREEN',
  VIOLET = 'VIOLET'
}

export type BigSmallType = 'Big' | 'Small';
export type BetStatus = 'Pending' | 'Win' | 'Loss';

export interface GameResult {
  id: string;
  period: string;
  number: number;
  colors: ColorType[];
  bigSmall: BigSmallType;
  timestamp: number;
}

export interface UserBet {
  id: string;
  period: string;
  amount: number;
  selection: ColorType | number | BigSmallType;
  status: BetStatus;
  payout?: number;
  timestamp: number;
}

export interface UserState {
  balance: number;
  id: string;
  phone: string;
  referralCode: string;
  avatarUrl?: string;
}

export enum Tab {
  HOME = 'HOME',
  HISTORY = 'HISTORY',
  WALLET = 'WALLET',
  PROFILE = 'PROFILE',
  AI_GEN = 'AI_GEN'
}

export type ImageSize = '1K' | '2K' | '4K';

import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet } from './types.ts';
import { INITIAL_BALANCE, ROUND_DURATION_SECONDS, COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AIGenerationView from './views/AIGenerationView.tsx';
import AuthModal from './components/AuthModal.tsx';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [user, setUser] = useState<UserState | null>(null);
  const [results, setResults] = useState<GameResult[]>([]);
  const [userBets, setUserBets] = useState<UserBet[]>([]);
  const [timeLeft, setTimeLeft] = useState(ROUND_DURATION_SECONDS);
  const [currentPeriod, setCurrentPeriod] = useState("20251223100051061");

  const generateResult = useCallback(() => {
    const num = Math.floor(Math.random() * 10);
    const bigSmall: BigSmallType = num >= 5 ? 'Big' : 'Small';
    const resultColors = COLORS_BY_NUMBER[num] as ColorType[];

    const newResult: GameResult = {
      id: Math.random().toString(36).substr(2, 9),
      period: currentPeriod,
      number: num,
      colors: resultColors,
      bigSmall: bigSmall,
      timestamp: Date.now()
    };

    setResults(prev => [newResult, ...prev].slice(0, 50));

    // Settle pending bets for this period
    setUserBets(prevBets => {
      let balanceAdjustment = 0;
      const updatedBets = prevBets.map(bet => {
        if (bet.period === currentPeriod && bet.status === 'Pending') {
          let isWin = false;
          let multiplier = 0;

          if (typeof bet.selection === 'number') {
            if (bet.selection === num) {
              isWin = true;
              multiplier = 9;
            }
          } else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bigSmall) {
              isWin = true;
              multiplier = 2;
            }
          } else {
            // Color selection
            if (resultColors.includes(bet.selection as ColorType)) {
              isWin = true;
              // Violet adjustment (usually pays less on combined wins but keeping it simple for demo)
              multiplier = bet.selection === ColorType.VIOLET ? 4.5 : 2;
            }
          }

          if (isWin) {
            const payout = bet.amount * multiplier;
            balanceAdjustment += payout;
            return { ...bet, status: 'Win' as const, payout };
          } else {
            return { ...bet, status: 'Loss' as const, payout: 0 };
          }
        }
        return bet;
      });

      if (balanceAdjustment > 0) {
        setUser(curr => curr ? { ...curr, balance: curr.balance + balanceAdjustment } : null);
      }
      return updatedBets;
    });

    const nextPeriodNum = BigInt(currentPeriod) + 1n;
    setCurrentPeriod(nextPeriodNum.toString());
  }, [currentPeriod]);

  // Timer logic
  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 0) {
          generateResult();
          return ROUND_DURATION_SECONDS;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [generateResult]);

  const handleLogin = (phone: string) => {
    setUser({
      id: "928374",
      phone: phone,
      balance: INITIAL_BALANCE,
      referralCode: "NEO777",
    });
  };

  const updateBalance = (amount: number) => {
    if (user) {
      setUser({ ...user, balance: user.balance + amount });
    }
  };

  const addUserBet = (bet: Omit<UserBet, 'id' | 'timestamp' | 'status'>) => {
    const newBet: UserBet = {
      ...bet,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      status: 'Pending'
    };
    setUserBets(prev => [newBet, ...prev]);
    updateBalance(-bet.amount);
  };

  const updateAvatar = (url: string) => {
    if (user) {
      setUser({ ...user, avatarUrl: url });
    }
  };

  if (!user) {
    return <AuthModal onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center selection:bg-purple-500/30">
      <div className="w-full max-w-md pb-20 relative">
        <header className="sticky top-0 z-40 bg-[#11131a] px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            <button className="text-xl">❮</button>
            <h1 className="text-xl font-bold font-orbitron tracking-tighter italic">Lottery 368</h1>
          </div>
          <div className="flex gap-4">
            <button className="text-xl">🎧</button>
            <button className="text-xl">🎵</button>
          </div>
        </header>

        <main className="overflow-y-auto">
          {activeTab === Tab.HOME && (
            <HomeView 
              timeLeft={timeLeft} 
              period={currentPeriod} 
              results={results}
              userBets={userBets}
              balance={user.balance}
              onBet={addUserBet}
            />
          )}
          {activeTab === Tab.HISTORY && (
            <HistoryView results={results} />
          )}
          {activeTab === Tab.AI_GEN && (
            <AIGenerationView onAvatarCreated={updateAvatar} />
          )}
          {activeTab === Tab.WALLET && (
            <WalletView balance={user.balance} onDeposit={() => updateBalance(1000)} />
          )}
          {activeTab === Tab.PROFILE && (
            <ProfileView user={user} />
          )}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
    </div>
  );
};

export default App;

