export interface GameResult {
  id: string;
  period: string;
  number: number;
  colors: ColorType[];
  bigSmall: BigSmallType;
  timestamp: number;
}

export interface UserBet {
  id: string;
  period: string;
  amount: number;
  selection: ColorType | number | BigSmallType;
  status: BetStatus;
  payout?: number;
  timestamp: number;
}

export interface UserState {
  balance: number;
  id: string;
  phone: string;
  referralCode: string;
  avatarUrl?: string;
}

