import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, Transaction, GameMode } from './types.ts';
import { INITIAL_BALANCE, COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import SupportView from './views/SupportView.tsx';
import AdminView from './views/AdminView.tsx';
import AuthModal from './components/AuthModal.tsx';
import AdOverlay from './components/AdOverlay.tsx';

const MODE_CONFIG: Record<GameMode, number> = {
  '30sec': 30,
  '1min': 60,
  '3min': 180,
  '5min': 300
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');
  const [user, setUser] = useState<UserState | null>(null);
  const [showAd, setShowAd] = useState(false);
  const [roundsPlayed, setRoundsPlayed] = useState(0);

  // Admin Control State
  const [nextResultOverrides, setNextResultOverrides] = useState<Record<GameMode, number | null>>({
    '30sec': null, '1min': null, '3min': null, '5min': null
  });

  // Multi-mode state
  const [results, setResults] = useState<Record<GameMode, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });
  const [timeLefts, setTimeLefts] = useState<Record<GameMode, number>>({
    '30sec': 30, '1min': 60, '3min': 180, '5min': 300
  });
  const [periods, setPeriods] = useState<Record<GameMode, string>>({
    '30sec': "20251223100051061",
    '1min': "20251223100062010",
    '3min': "20251223100073005",
    '5min': "20251223100084001"
  });

  const [userBets, setUserBets] = useState<UserBet[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const generateResult = useCallback((mode: GameMode) => {
    let num: number;
    const override = nextResultOverrides[mode];

    if (override !== null) {
      num = override;
      setNextResultOverrides(prev => ({ ...prev, [mode]: null }));
    } else {
      num = Math.floor(Math.random() * 10);
    }

    const bigSmall: BigSmallType = num >= 5 ? 'Big' : 'Small';
    const resultColors = COLORS_BY_NUMBER[num] as ColorType[];
    const currentPeriod = periods[mode];

    const newResult: GameResult = {
      id: Math.random().toString(36).substr(2, 9),
      period: currentPeriod,
      number: num,
      colors: resultColors,
      bigSmall: bigSmall,
      timestamp: Date.now()
    };

    setResults(prev => ({
      ...prev,
      [mode]: [newResult, ...prev[mode]].slice(0, 50)
    }));

    // Trigger Ad every 2 rounds globally
    setRoundsPlayed(prev => {
      const next = prev + 1;
      if (next % 2 === 0) {
        setShowAd(true);
      }
      return next;
    });

    setUserBets(prevBets => {
      let balanceAdjustment = 0;
      const updatedBets = prevBets.map(bet => {
        if (bet.mode === mode && bet.period === currentPeriod && bet.status === 'Pending') {
          let isWin = false;
          let multiplier = 0;

          if (typeof bet.selection === 'number') {
            if (bet.selection === num) {
              isWin = true;
              multiplier = 9;
            }
          } else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bigSmall) {
              isWin = true;
              multiplier = 1.98;
            }
          } else {
            if (resultColors.includes(bet.selection as ColorType)) {
              isWin = true;
              multiplier = bet.selection === ColorType.VIOLET ? 4.5 : 2;
            }
          }

          if (isWin) {
            const payout = bet.amount * multiplier;
            balanceAdjustment += payout;
            return { ...bet, status: 'Win' as const, payout };
          } else {
            return { ...bet, status: 'Loss' as const, payout: 0 };
          }
        }
        return bet;
      });

      if (balanceAdjustment > 0) {
        setUser(curr => curr ? { ...curr, balance: curr.balance + balanceAdjustment } : null);
      }
      return updatedBets;
    });

    setPeriods(prev => ({
      ...prev,
      [mode]: (BigInt(prev[mode]) + 1n).toString()
    }));
  }, [periods, nextResultOverrides]);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLefts(prev => {
        const newTimeLefts = { ...prev };
        (Object.keys(MODE_CONFIG) as GameMode[]).forEach(mode => {
          if (newTimeLefts[mode] <= 0) {
            generateResult(mode);
            newTimeLefts[mode] = MODE_CONFIG[mode];
          } else {
            newTimeLefts[mode] -= 1;
          }
        });
        return newTimeLefts;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [generateResult]);

  const handleLogin = (phone: string, referralCode?: string) => {
    // Both receive 500 coins bonus if referral used
    const bonus = referralCode ? 500 : 0;
    setUser({
      id: Math.floor(100000 + Math.random() * 900000).toString(),
      phone: phone,
      balance: INITIAL_BALANCE + bonus,
      referralCode: "RITIK" + Math.floor(100 + Math.random() * 899),
    });
    if (bonus > 0) {
      alert("Referral Applied! 500 Coins bonus added.");
    }
  };

  const updateBalance = (amount: number) => {
    if (user) {
      setUser({ ...user, balance: user.balance + amount });
    }
  };

  const addUserBet = (bet: Omit<UserBet, 'id' | 'timestamp' | 'status' | 'mode' | 'period'>) => {
    const newBet: UserBet = {
      ...bet,
      mode: activeMode,
      period: periods[activeMode],
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      status: 'Pending'
    };
    setUserBets(prev => [newBet, ...prev]);
    updateBalance(-bet.amount);
  };

  const handleDeposit = (utr: string) => {
    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'Deposit',
      amount: 20,
      coins: 200,
      status: 'Pending',
      timestamp: Date.now(),
      utr: utr
    };
    setTransactions(prev => [newTx, ...prev]);
    alert("Deposit request submitted! 200 coins will be added after verification.");

    setTimeout(() => {
      setTransactions(prev => prev.map(t => {
        if (t.id === newTx.id) {
          updateBalance(200);
          return { ...t, status: 'Completed' };
        }
        return t;
      }));
    }, 5000);
  };

  if (!user) {
    return <AuthModal onLogin={handleLogin} />;
  }

  // Admin access check
  const isAdmin = user.phone === '6207559408';

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center selection:bg-purple-500/30">
      <div className="w-full max-w-md pb-20 relative">
        {showAd && <AdOverlay onClose={() => setShowAd(false)} />}

        <header className="sticky top-0 z-40 bg-[#11131a] px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            <button className="text-xl">❮</button>
            <h1 className="text-xl font-bold font-orbitron tracking-tighter italic">Ritik Club</h1>
          </div>
          <div className="flex gap-4">
            <button className="text-xl" onClick={() => setActiveTab(Tab.SUPPORT)}>🎧</button>
            <button className="text-xl">🎵</button>
          </div>
        </header>

        <main className="overflow-y-auto">
          {activeTab === Tab.HOME && (
            <HomeView 
              activeMode={activeMode}
              setActiveMode={setActiveMode}
              timeLeft={timeLefts[activeMode]} 
              period={periods[activeMode]} 
              results={results[activeMode]}
              userBets={userBets.filter(b => b.mode === activeMode)}
              balance={user.balance}
              onBet={addUserBet}
            />
          )}
          {activeTab === Tab.HISTORY && (
            <HistoryView results={results[activeMode]} />
          )}
          {activeTab === Tab.SUPPORT && (
            <SupportView />
          )}
          {activeTab === Tab.ADMIN && isAdmin && (
            <AdminView 
              overrides={nextResultOverrides} 
              onSetOverride={(mode, num) => setNextResultOverrides(prev => ({ ...prev, [mode]: num }))} 
            />
          )}
          {activeTab === Tab.WALLET && (
            <WalletView 
              balance={user.balance} 
              onDeposit={handleDeposit} 
              transactions={transactions}
            />
          )}
          {activeTab === Tab.PROFILE && (
            <ProfileView user={user} setTab={setActiveTab} />
          )}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
    </div>
  );
};

export default App;

