          didParticipate = true;
          let isWin = false;
          let multiplier = 0;

          if (typeof bet.selection === 'number') {
            if (bet.selection === num) { isWin = true; multiplier = 9; }
          } else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bigSmall) { isWin = true; multiplier = 1.98; }
          } else {
            if (resultColors.includes(bet.selection as ColorType)) {
              isWin = true;
              multiplier = (bet.selection === ColorType.VIOLET) ? 4.5 : 2;
              if ((num === 0 || num === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) {
                multiplier = 1.5;
              }
            }
          }

          if (isWin) {
            const payout = bet.amount * multiplier;
            sessionProfit += payout;
            return { ...bet, status: 'Win' as const, payout };
          } else {
            return { ...bet, status: 'Loss' as const, payout: 0 };
          }
        }
        return bet;
      });

      if (sessionProfit > 0) {
        setUser(curr => curr ? { ...curr, balance: curr.balance + sessionProfit } : null);
      }
      return updatedBets;
    });

    if (mode === activeMode && didParticipate) {
      setLastResult(newResult);
      setLastProfit(sessionProfit);
      setUserParticipated(didParticipate);
      setIsResultModalOpen(true);
    }

    setPeriods(prev => ({
      ...prev,
      [mode]: (BigInt(prev[mode]) + 1n).toString()
    }));
  }, [periods, nextResultOverrides, activeMode]);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLefts(prev => {
        const next = { ...prev };
        (Object.keys(MODE_CONFIG) as GameMode[]).forEach(mode => {
          if (next[mode] <= 1) {
            generateResult(mode);
            next[mode] = MODE_CONFIG[mode];
          } else {
            next[mode] -= 1;
          }
        });
        return next;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [generateResult]);

  const handleLogin = (phone: string, referralCode?: string) => {
    setUser({
      id: "ID" + Math.floor(100000 + Math.random() * 899999),
      phone: phone,
      balance: INITIAL_BALANCE + (referralCode ? 500 : 0),
      referralCode: "RC" + Math.floor(1000 + Math.random() * 8999),
    });
  };

  const addUserBet = (bet: Omit<UserBet, 'id' | 'timestamp' | 'status' | 'mode' | 'period'>) => {
    const newBet: UserBet = {
      ...bet,
      mode: activeMode,
      period: periods[activeMode],
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      status: 'Pending'
    };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => curr ? { ...curr, balance: curr.balance - bet.amount } : null);
  };

  if (!user) return <AuthModal onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center overflow-x-hidden">
      <div className="w-full max-w-md pb-20 relative shadow-2xl bg-[#11131a]">
        {isResultModalOpen && (
          <ResultModal 
            result={lastResult} 
            userProfit={lastProfit} 
            hasBet={userParticipated}
            onClose={() => setIsResultModalOpen(false)} 
          />
        )}

        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-lg px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-sm shadow-lg shadow-blue-900/40">R</div>
             <div>
               <h1 className="text-xl font-black font-orbitron tracking-tighter italic bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-500">Ritik Club</h1>
               <div className="flex items-center gap-1.5 -mt-1">
                 <span className="status-dot"></span>
                 <span className="text-[7px] font-black uppercase tracking-widest text-green-500/80">Server Online</span>
               </div>
             </div>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setActiveTab(Tab.SUPPORT)} className="w-10 h-10 flex items-center justify-center bg-white/5 rounded-full hover:bg-white/10 transition-all">🎧</button>
            <button className="w-10 h-10 flex items-center justify-center bg-white/5 rounded-full">🔔</button>
          </div>
        </header>

        <main className="animate-in fade-in duration-500">
          {activeTab === Tab.HOME && (
            <HomeView 
              activeMode={activeMode}
              setActiveMode={setActiveMode}
              timeLeft={timeLefts[activeMode]} 
              period={periods[activeMode]} 
              results={results[activeMode]}
              userBets={userBets.filter(b => b.mode === activeMode)}
              balance={user.balance}
              onBet={addUserBet}
            />
          )}
          {activeTab === Tab.HISTORY && (
            <HistoryView 
              results={results[activeMode]} 
              userBets={userBets.filter(b => b.mode === activeMode)}
            />
          )}
          {activeTab === Tab.SUPPORT && <SupportView />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} onDeposit={() => {}} transactions={transactions} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} />}
          {activeTab === Tab.ADMIN && user.phone === '6207559408' && (
            <AdminView overrides={nextResultOverrides} onSetOverride={(mode, num) => setNextResultOverrides(prev => ({ ...prev, [mode]: num }))} />
          )}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
    </div>
  );
};

