import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, Transaction, GameMode } from './types.ts';
import { INITIAL_BALANCE, COLORS_BY_NUMBER, VIP_LEVELS } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import SupportView from './views/SupportView.tsx';
import AdminView from './views/AdminView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';

const MODE_CONFIG: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('rc_txs');
    return saved ? JSON.parse(saved) : [];
  });

  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [userParticipated, setUserParticipated] = useState<boolean>(false);

  const [nextResultOverrides, setNextResultOverrides] = useState<Record<GameMode, number | null>>({
    '30sec': null, '1min': null, '3min': null, '5min': null
  });

  const [results, setResults] = useState<Record<GameMode, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });
  const [timeLefts, setTimeLefts] = useState<Record<GameMode, number>>({
    '30sec': 30, '1min': 60, '3min': 180, '5min': 300
  });
  const [periods, setPeriods] = useState<Record<GameMode, string>>({
    '30sec': "2025061510001", '1min': "2025061520001", '3min': "2025061530001", '5min': "2025061540001"
  });

  useEffect(() => {
    if (user) localStorage.setItem('rc_user', JSON.stringify(user));
  }, [user]);

  const calculateVipLevel = (turnover: number): number => {
    let currentVip = 1;
    for (const tier of VIP_LEVELS) {
      if (turnover >= tier.expNeeded) currentVip = tier.level;
      else break;
    }
    return currentVip;
  };

  const generateResult = useCallback((mode: GameMode) => {
    let num = nextResultOverrides[mode] ?? Math.floor(Math.random() * 10);
    if (nextResultOverrides[mode] !== null) setNextResultOverrides(prev => ({ ...prev, [mode]: null }));

    const currentPeriod = periods[mode];
    const newResult: GameResult = {
      id: Math.random().toString(36).substr(2, 9),
      period: currentPeriod,
      number: num,
      colors: COLORS_BY_NUMBER[num] as ColorType[],
      bigSmall: num >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [newResult, ...prev[mode]].slice(0, 50) }));

    let profit = 0;
    let played = false;

    setUserBets(prev => prev.map(bet => {
      if (bet.mode === mode && bet.period === currentPeriod && bet.status === 'Pending') {
        played = true;
        let win = false;
        let mult = 0;
        if (typeof bet.selection === 'number') { if (bet.selection === num) { win = true; mult = 9; } }
        else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === (num >= 5 ? 'Big' : 'Small')) { win = true; mult = 1.98; } }
        else if (newResult.colors.includes(bet.selection as ColorType)) { win = true; mult = 2; }

        if (win) { profit += bet.amount * mult; return { ...bet, status: 'Win', payout: bet.amount * mult }; }
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (profit > 0) setUser(c => c ? { ...c, balance: c.balance + profit } : null);
    if (mode === activeMode && played) { setLastResult(newResult); setLastProfit(profit); setUserParticipated(true); setIsResultModalOpen(true); }
    setPeriods(prev => ({ ...prev, [mode]: (BigInt(prev[mode]) + 1n).toString() }));
  }, [periods, nextResultOverrides, activeMode]);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLefts(prev => {
        const next = { ...prev };
        (Object.keys(MODE_CONFIG) as GameMode[]).forEach(m => {
          if (next[m] <= 1) { generateResult(m); next[m] = MODE_CONFIG[m]; }
          else next[m] -= 1;
        });
        return next;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [generateResult]);

  const handleBet = (bet: any) => {
    const newBet: UserBet = { ...bet, mode: activeMode, period: periods[activeMode], id: Math.random().toString(36).substr(2, 9), timestamp: Date.now(), status: 'Pending' };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const turn = curr.totalTurnover + bet.amount;
      return { ...curr, balance: curr.balance - bet.amount, totalTurnover: turn, vipLevel: calculateVipLevel(turn) };
    });
  };

  if (!user) return <AuthModal onLogin={(p) => setUser({ id: "ID"+Date.now().toString().slice(-6), phone: p, balance: INITIAL_BALANCE, referralCode: "RC"+Math.floor(1000+Math.random()*8999), vipLevel: 1, totalTurnover: 0 })} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a]">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={userParticipated} onClose={() => setIsResultModalOpen(false)} />}
        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-lg px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron">Ritik Club</h1>
              <span className="text-[8px] font-bold text-yellow-500 bg-yellow-500/10 px-1.5 rounded-full">VIP {user.vipLevel}</span>
            </div>
          </div>
        </header>
        <main>
          {activeTab === Tab.HOME && <HomeView activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={timeLefts[activeMode]} period={periods[activeMode]} results={results[activeMode]} userBets={userBets} balance={user.balance} onBet={handleBet} vipLevel={user.vipLevel} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={transactions} onDeposit={()=>{}} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets.filter(b=>b.mode===activeMode)} />}
          {activeTab === Tab.SUPPORT && <SupportView />}
          {activeTab === Tab.ADMIN && <AdminView overrides={nextResultOverrides} onSetOverride={(m, n) => setNextResultOverrides(p => ({ ...p, [m]: n }))} />}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
    </div>
  );
};

export default App;

