import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, GameMode, GameType } from './types.ts';
import { INITIAL_BALANCE, COLORS_BY_NUMBER, VIP_LEVELS } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import SupportView from './views/SupportView.tsx';
import AdminView from './views/AdminView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';
import CricketGame from './views/CricketGame.tsx';
import VortexGame from './views/VortexGame.tsx';
import ChickenGame from './views/ChickenGame.tsx';

const MODE_DURATIONS: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });

  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<GameMode, string>>({
    '30sec': '', '1min': '', '3min': '', '5min': ''
  });
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<GameMode, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  // Deterministic engine
  const getDeterministicResult = (period: string): number => {
    let hash = 0;
    for (let i = 0; i < period.length; i++) {
      hash = ((hash << 5) - hash) + period.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash) % 10;
  };

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const date = new Date();
    const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
    const modeIdx = Object.keys(MODE_DURATIONS).indexOf(mode);
    return { periodId: `${dateStr}${modeIdx}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const num = getDeterministicResult(period);
    const result: GameResult = {
      id: Math.random().toString(36).substr(2, 5),
      period: period,
      number: num,
      colors: COLORS_BY_NUMBER[num] as ColorType[],
      bigSmall: num >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...prev[mode]].slice(0, 50) }));

    let profit = 0;
    let hadBet = false;
    setUserBets(prev => {
      const newBets = prev.map(bet => {
        if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
          hadBet = true;
          let win = false;
          let mult = 0;
          if (typeof bet.selection === 'number') { if (bet.selection === num) { win = true; mult = 9; } }
          else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.98; } }
          else if (result.colors.includes(bet.selection as ColorType)) {
             win = true; mult = 2;
             if ((num === 0 || num === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          }
          if (win) { profit += bet.amount * mult; return { ...bet, status: 'Win', payout: bet.amount * mult }; }
          return { ...bet, status: 'Loss', payout: 0 };
        }
        return bet;
      });
      if (profit > 0) setUser(curr => curr ? { ...curr, balance: curr.balance + profit } : null);
      return newBets;
    });

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result);
      setLastProfit(profit);
      setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] !== '' && lastProcessedPeriod[mode] !== periodId) {
          processDraw(mode, lastProcessedPeriod[mode]);
        }
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  useEffect(() => {
    if (user) localStorage.setItem('rc_user', JSON.stringify(user));
    localStorage.setItem('rc_bets', JSON.stringify(userBets.slice(0, 100)));
  }, [user, userBets]);

  const handleBet = (bet: any) => {
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = { 
      ...bet, 
      mode: activeMode, 
      period: periodId, 
      id: "BT" + Math.random().toString(36).substr(2, 5).toUpperCase(), 
      timestamp: Date.now(), 
      status: 'Pending' 
    };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const turn = curr.totalTurnover + bet.amount;
      return { ...curr, balance: curr.balance - bet.amount, totalTurnover: turn, vipLevel: 1 };
    });
  };

  const sync = getSyncData(activeMode);

  if (!user) return <AuthModal onLogin={(p) => setUser({ id: "ID"+Date.now().toString().slice(-6), phone: p, balance: INITIAL_BALANCE, referralCode: "RC"+Math.floor(1000+Math.random()*8999), vipLevel: 1, totalTurnover: 0 })} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}

        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && (
              <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>
            )}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black shadow-lg">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <div className="flex items-center gap-1.5 -mt-1">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                <span className="text-[8px] font-black text-yellow-500 bg-yellow-500/10 px-1.5 rounded-full">VIP {user.vipLevel}</span>
              </div>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toLocaleString()}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.CHICKEN && <ChickenGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}

          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={[]} onDeposit={()=>{}} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.SUPPORT && <SupportView />}
          {activeTab === Tab.ADMIN && <AdminView overrides={{'30sec':null, '1min':null, '3min':null, '5min':null} as any} onSetOverride={()=>{}} />}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} />
      </div>
    </div>
  );
};

export default App;

