  const [multiplier, setMultiplier] = useState(1.00);
  const [isCrashed, setIsCrashed] = useState(false);
  const [betAmount, setBetAmount] = useState(10);
  const [hasBet, setHasBet] = useState(false);
  const [crashPoint, setCrashPoint] = useState(2.50);
  const [gameState, setGameState] = useState<'WAITING' | 'FLYING' | 'CRASHED'>('WAITING');
  const [timer, setTimer] = useState(5);

  useEffect(() => {
    let interval: any;
    if (gameState === 'WAITING') {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev <= 1) {
            setGameState('FLYING');
            setMultiplier(1.00);
            setIsCrashed(false);
            setCrashPoint(1 + Math.random() * 5); // Simple crash point generator
            return 5;
          }
          return prev - 1;
        });
      }, 1000);
    } else if (gameState === 'FLYING') {
      interval = setInterval(() => {
        setMultiplier(prev => {
          const next = prev + 0.05;
          if (next >= crashPoint) {
            setGameState('CRASHED');
            setIsCrashed(true);
            setHasBet(false);
            setTimeout(() => setGameState('WAITING'), 3000);
            return crashPoint;
          }
          return next;
        });
      }, 100);
    }
    return () => clearInterval(interval);
  }, [gameState, crashPoint]);

  const handleBet = () => {
    if (balance >= betAmount) {
      onUpdateBalance(-betAmount);
      setHasBet(true);
    }
  };

  const handleCashOut = () => {
    if (hasBet && !isCrashed) {
      const win = betAmount * multiplier;
      onUpdateBalance(win);
      setHasBet(false);
      alert(`Casheed out at ${multiplier.toFixed(2)}x! Won 🪙 ${win.toLocaleString()}`);
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div className="h-64 bg-[#11131a] rounded-[2rem] border border-red-500/20 relative overflow-hidden flex flex-col items-center justify-center">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20"></div>

        {gameState === 'WAITING' ? (
          <div className="text-center z-10">
            <p className="text-xs text-red-500 font-black uppercase tracking-[0.3em] mb-2">Next Round In</p>
            <p className="text-6xl font-black font-orbitron">{timer}s</p>
          </div>
        ) : (
          <div className="text-center z-10 transition-all">
            <p className={`text-6xl font-black font-orbitron ${isCrashed ? 'text-red-600' : 'text-white'}`}>
              {multiplier.toFixed(2)}x
            </p>
            {isCrashed && <p className="text-sm font-black text-red-600 uppercase mt-2">FLEW AWAY!</p>}
            {!isCrashed && (
              <div className="mt-4 animate-bounce">
                <span className="text-4xl">✈️</span>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 flex flex-col gap-4">
        <div className="flex justify-between items-center bg-black/20 p-4 rounded-2xl">
           <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} className="w-10 h-10 bg-white/5 rounded-full font-black text-lg">-</button>
           <span className="text-lg font-black font-orbitron">🪙 {betAmount}</span>
           <button onClick={() => setBetAmount(betAmount + 10)} className="w-10 h-10 bg-white/5 rounded-full font-black text-lg">+</button>
        </div>

        {hasBet ? (
          <button 
            disabled={gameState !== 'FLYING' || isCrashed}
            onClick={handleCashOut}
            className="w-full py-6 bg-yellow-500 text-black rounded-3xl font-black text-xl uppercase shadow-2xl disabled:opacity-50"
          >
            Cash Out {(betAmount * multiplier).toFixed(2)}
          </button>
        ) : (
          <button 
            disabled={gameState !== 'WAITING'}
            onClick={handleBet}
            className="w-full py-6 bg-red-600 text-white rounded-3xl font-black text-xl uppercase shadow-2xl disabled:opacity-50"
          >
            Place Bet
          </button>
        )}
      </div>

      <p className="text-center text-[9px] text-gray-600 font-bold uppercase tracking-widest">Global Aviator Engine v1.0 - SYNCED</p>
    </div>
  );
};

export default AviatorGame;

import React, { useState } from 'react';

interface MinesGameProps {
  balance: number;
  onUpdateBalance: (amount: number) => void;
}

const MinesGame: React.FC<MinesGameProps> = ({ balance, onUpdateBalance }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [grid, setGrid] = useState(Array(25).fill(null));
  const [mineCount, setMineCount] = useState(3);
  const [mines, setMines] = useState<number[]>([]);
  const [revealed, setRevealed] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);

  const startGame = () => {
    if (balance < bet) return;
    onUpdateBalance(-bet);
    const newMines: number[] = [];
    while (newMines.length < mineCount) {
      const r = Math.floor(Math.random() * 25);
      if (!newMines.includes(r)) newMines.push(r);
    }
    setMines(newMines);
    setRevealed([]);
    setGameOver(false);
    setIsPlaying(true);
  };

  const handleTile = (idx: number) => {
    if (!isPlaying || revealed.includes(idx) || gameOver) return;

    if (mines.includes(idx)) {
      setGameOver(true);
      setIsPlaying(false);
      alert("BOOM! You hit a mine.");
    } else {
      setRevealed(prev => [...prev, idx]);
    }
  };

  const cashOut = () => {
    if (!isPlaying) return;
    const multiplier = 1 + (revealed.length * 0.2);
    const win = bet * multiplier;
    onUpdateBalance(win);
    setIsPlaying(false);
    alert(`Cashed out 🪙 ${win.toFixed(2)}!`);
  };

  return (
    <div className="p-4 space-y-6">
      <div className="grid grid-cols-5 gap-2 bg-[#11131a] p-4 rounded-[2rem] border border-white/5">
        {grid.map((_, i) => (
          <button 
            key={i} 
            onClick={() => handleTile(i)}
            className={`aspect-square rounded-xl transition-all flex items-center justify-center text-xl ${
              revealed.includes(i) ? 'bg-green-600 shadow-inner' : 
              gameOver && mines.includes(i) ? 'bg-red-600' : 'bg-[#1e2330] border border-white/5'
            }`}
          >
            {revealed.includes(i) ? '💎' : gameOver && mines.includes(i) ? '💣' : ''}
          </button>
        ))}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4">
        <div className="flex gap-4">
          <div className="flex-1 bg-black/20 p-4 rounded-2xl">
            <p className="text-[10px] text-gray-500 uppercase font-black">Bet Amount</p>
            <p className="text-sm font-black font-orbitron">🪙 {bet}</p>
          </div>
          <div className="flex-1 bg-black/20 p-4 rounded-2xl">
            <p className="text-[10px] text-gray-500 uppercase font-black">Mines</p>
            <select value={mineCount} onChange={(e) => setMineCount(Number(e.target.value))} className="bg-transparent text-sm font-black font-orbitron outline-none w-full">
              {[1,3,5,10].map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        {isPlaying ? (
          <button onClick={cashOut} className="w-full py-5 bg-yellow-500 text-black rounded-3xl font-black text-lg uppercase shadow-xl">
            Cash Out {(bet * (1 + revealed.length * 0.2)).toFixed(2)}
          </button>
        ) : (
          <button onClick={startGame} className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black text-lg uppercase shadow-xl">
            Start Game
          </button>
        )}
      </div>
    </div>
  );
};

export default MinesGame;

import React, { useState } from 'react';

const CricketGame: React.FC<{balance: number, onUpdateBalance: (a: number)=>void}> = ({balance, onUpdateBalance}) => {
  const [bet, setBet] = useState(10);
  const [isRolling, setIsRolling] = useState(false);
  const [lastRun, setLastRun] = useState<null | number>(null);

  const placePrediction = (predict: number) => {
    if (balance < bet) return;
    onUpdateBalance(-bet);
    setIsRolling(true);

    setTimeout(() => {
      const actual = [0, 1, 2, 4, 6][Math.floor(Math.random() * 5)];
      setLastRun(actual);
      setIsRolling(false);

      if (actual === predict) {
        const mult = actual === 6 ? 6 : actual === 4 ? 4 : 2;
        onUpdateBalance(bet * mult);
        alert(`BOUDARY! You predicted ${actual} runs. Won ${bet * mult}!`);
      } else {
        alert(`Dotted! Result was ${actual} runs.`);
      }
    }, 1500);
  };

  return (
    <div className="p-4 space-y-6">
      <div className="h-48 bg-gradient-to-br from-green-900 to-emerald-950 rounded-[2rem] border border-green-500/20 flex flex-col items-center justify-center relative overflow-hidden">
