          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4">
        <p className="text-center text-[10px] text-gray-500 uppercase font-black tracking-widest">Predict Next Ball Runs</p>
        <div className="grid grid-cols-3 gap-3">
          {[0, 1, 2, 4, 6].map(run => (
            <button 
              key={run} 
              disabled={isRolling}
