            >
              {run}
            </button>
          ))}
        </div>

        <div className="flex justify-between items-center bg-black/20 p-4 rounded-2xl">
          <button onClick={() => setBet(Math.max(10, bet-10))} className="w-8 h-8 bg-white/5 rounded-full font-black">-</button>
          <p className="text-sm font-black font-orbitron">🪙 {bet}</p>
          <button onClick={() => setBet(bet+10)} className="w-8 h-8 bg-white/5 rounded-full font-black">+</button>
        </div>
      </div>
    </div>
  );
};

