import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, GameMode, GameType } from './types.ts';
import { INITIAL_BALANCE, COLORS_BY_NUMBER, VIP_LEVELS } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import SupportView from './views/SupportView.tsx';
import AdminView from './views/AdminView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';
import CricketGame from './views/CricketGame.tsx';
import VortexGame from './views/VortexGame.tsx';
import ChickenGame from './views/ChickenGame.tsx';

const MODE_DURATIONS: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });

  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<GameMode, string>>({
    '30sec': '', '1min': '', '3min': '', '5min': ''
  });
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<GameMode, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  // Global Deterministic Seed Generator
  const getDeterministicValue = (period: string, salt: string = "default"): number => {
    const combined = period + salt;
    let hash = 0;
    for (let i = 0; i < combined.length; i++) {
      hash = ((hash << 5) - hash) + combined.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash);
  };

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const date = new Date();
    const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
    const modeIdx = Object.keys(MODE_DURATIONS).indexOf(mode);
    return { periodId: `${dateStr}${modeIdx}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const seedValue = getDeterministicValue(period, "wingo");
    const num = seedValue % 10;
    const result: GameResult = {
      id: "WIN" + seedValue.toString(36).substr(0, 5).toUpperCase(),
      period: period,
      number: num,
      colors: COLORS_BY_NUMBER[num] as ColorType[],
      bigSmall: num >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...prev[mode]].slice(0, 50) }));

    let profit = 0;
    let hadBet = false;
    setUserBets(prev => {
      const newBets = prev.map(bet => {
        if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
          hadBet = true;
          let win = false;
          let mult = 0;
          if (typeof bet.selection === 'number') { if (bet.selection === num) { win = true; mult = 9; } }
          else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.98; } }
          else if (result.colors.includes(bet.selection as ColorType)) {
             win = true; mult = 2;
             if ((num === 0 || num === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          }
          if (win) { profit += bet.amount * mult; return { ...bet, status: 'Win', payout: bet.amount * mult }; }
          return { ...bet, status: 'Loss', payout: 0 };
        }
        return bet;
      });
      if (profit > 0) setUser(curr => curr ? { ...curr, balance: curr.balance + profit } : null);
      return newBets;
    });

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result);
      setLastProfit(profit);
      setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] !== '' && lastProcessedPeriod[mode] !== periodId) {
          processDraw(mode, lastProcessedPeriod[mode]);
        }
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  useEffect(() => {
    if (user) localStorage.setItem('rc_user', JSON.stringify(user));
    localStorage.setItem('rc_bets', JSON.stringify(userBets.slice(0, 100)));
  }, [user, userBets]);

  const handleBet = (bet: any) => {
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = { 
      ...bet, 
      mode: activeMode, 
      period: periodId, 
      id: "BT" + Math.random().toString(36).substr(2, 5).toUpperCase(), 
      timestamp: Date.now(), 
      status: 'Pending' 
    };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const turn = curr.totalTurnover + bet.amount;
      return { ...curr, balance: curr.balance - bet.amount, totalTurnover: turn, vipLevel: 1 };
    });
  };

  const sync = getSyncData(activeMode);

  if (!user) return <AuthModal onLogin={(p) => setUser({ id: "ID"+Date.now().toString().slice(-6), phone: p, balance: INITIAL_BALANCE, referralCode: "RC"+Math.floor(1000+Math.random()*8999), vipLevel: 1, totalTurnover: 0 })} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}

        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && (
              <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>
            )}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black shadow-lg">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <div className="flex items-center gap-1.5 -mt-1">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                <span className="text-[8px] font-black text-yellow-500 bg-yellow-500/10 px-1.5 rounded-full">VIP {user.vipLevel}</span>
              </div>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toLocaleString()}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}
          {activeTab === Tab.HOME && activeGame === GameType.CHICKEN && <ChickenGame balance={user.balance} onUpdateBalance={(v) => setUser(u => u ? {...u, balance: u.balance + v} : null)} />}

          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={[]} onDeposit={()=>{}} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.SUPPORT && <SupportView />}
          {activeTab === Tab.ADMIN && <AdminView overrides={{'30sec':null, '1min':null, '3min':null, '5min':null} as any} onSetOverride={()=>{}} />}
        </main>

        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} />
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

interface AviatorGameProps {
  balance: number;
  onUpdateBalance: (amount: number) => void;
}

const AviatorGame: React.FC<AviatorGameProps> = ({ balance, onUpdateBalance }) => {
  const [multiplier, setMultiplier] = useState(1.00);
  const [timeLeft, setTimeLeft] = useState(0);
  const [period, setPeriod] = useState("");
  const [isFlying, setIsFlying] = useState(false);
  const [isCrashed, setIsCrashed] = useState(false);
  const [crashPoint, setCrashPoint] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [hasBet, setHasBet] = useState(false);
  const [cashedOut, setCashedOut] = useState(false);

  // Aviator Global Sync Engine
  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000; // 30 seconds per round
      const cycleTime = now % periodDuration;
      const waitTime = 10000; // 10 seconds betting/waiting time
      const flightTime = periodDuration - waitTime;

      const currentPeriod = Math.floor(now / periodDuration).toString();
      setPeriod(currentPeriod);

      // Deterministic Crash Point for this period
      let hash = 0;
      const seed = currentPeriod + "aviator_v1";
      for (let i = 0; i < seed.length; i++) {
        hash = ((hash << 5) - hash) + seed.charCodeAt(i);
        hash |= 0;
      }
      const deterministicCrash = 1 + (Math.abs(hash) % 500) / 100; // 1.00 to 6.00
      setCrashPoint(deterministicCrash);

      if (cycleTime < waitTime) {
        // Waiting Phase
        setIsFlying(false);
        setIsCrashed(false);
        setTimeLeft(Math.ceil((waitTime - cycleTime) / 1000));
        setMultiplier(1.00);
        if (cycleTime < 500) { 
           setHasBet(false);
           setCashedOut(false);
        }
      } else {
        // Flying Phase
        setIsFlying(true);
        const elapsedFlight = (cycleTime - waitTime) / 1000;
        // Simple curve: multiplier = 1.05 ^ elapsedSeconds
        const currentMult = Math.pow(1.08, elapsedFlight);

        if (currentMult >= deterministicCrash) {
          setIsCrashed(true);
          setMultiplier(deterministicCrash);
        } else {
          setMultiplier(currentMult);
        }
      }
    }, 100);
    return () => clearInterval(interval);
  }, []);

  const handlePlaceBet = () => {
    if (!isFlying && !hasBet && balance >= betAmount) {
      onUpdateBalance(-betAmount);
      setHasBet(true);
    }
  };

  const handleCashOut = () => {
    if (isFlying && !isCrashed && hasBet && !cashedOut) {
      const win = betAmount * multiplier;
      onUpdateBalance(win);
      setCashedOut(true);
      alert(`Cashed out at ${multiplier.toFixed(2)}x! Won 🪙 ${win.toFixed(0)}`);
    }
  };

  return (
    <div className="p-4 space-y-4 animate-in fade-in duration-500">
      {/* Flight Display */}
      <div className="h-64 bg-[#0a0c10] rounded-[2rem] border border-red-500/20 relative overflow-hidden flex flex-col items-center justify-center">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/10 via-transparent to-transparent opacity-50"></div>

        {!isFlying ? (
          <div className="text-center z-10 scale-in-center">
            <p className="text-[10px] text-red-500 font-black uppercase tracking-[0.3em] mb-2">Next Round Starts In</p>
            <p className="text-6xl font-black font-orbitron text-white">{timeLeft}s</p>
            <p className="text-[8px] text-gray-600 mt-4 uppercase font-bold tracking-widest">Global Synced Engine</p>
          </div>
        ) : (
          <div className="text-center z-10 transition-all duration-300">
            <p className={`text-7xl font-black font-orbitron transition-colors ${isCrashed ? 'text-red-600' : 'text-white'}`}>
              {multiplier.toFixed(2)}x
            </p>
            {isCrashed ? (
              <p className="text-sm font-black text-red-600 uppercase mt-2 tracking-widest animate-pulse">FLEW AWAY!</p>
            ) : (
              <div className="mt-8 relative h-12 w-full flex justify-center items-center">
                 <div className="text-5xl animate-bounce">✈️</div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Betting Controls */}
      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4 shadow-2xl">
        <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
           <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} className="w-12 h-12 bg-white/5 rounded-2xl font-black text-xl active:scale-90 transition-transform">-</button>
           <div className="text-center">
              <p className="text-[9px] text-gray-500 font-bold uppercase mb-1">Bet Amount</p>
              <span className="text-xl font-black font-orbitron">🪙 {betAmount}</span>
           </div>
           <button onClick={() => setBetAmount(betAmount + 10)} className="w-12 h-12 bg-white/5 rounded-2xl font-black text-xl active:scale-90 transition-transform">+</button>
        </div>

        {!isFlying ? (
          <button 
            disabled={hasBet}
            onClick={handlePlaceBet}
            className={`w-full py-6 rounded-3xl font-black text-xl uppercase shadow-2xl transition-all active:scale-95 ${
              hasBet ? 'bg-gray-800 text-gray-500 cursor-not-allowed border border-white/5' : 'bg-green-600 text-white shadow-green-900/40 border border-green-400/20'
            }`}
          >
            {hasBet ? 'Waiting for Start...' : 'Place Bet'}
          </button>
        ) : (
          <button 
            disabled={isCrashed || cashedOut || !hasBet}
            onClick={handleCashOut}
            className={`w-full py-6 rounded-3xl font-black text-xl uppercase shadow-2xl transition-all active:scale-95 ${
              isCrashed || cashedOut || !hasBet ? 'bg-gray-800 text-gray-500 cursor-not-allowed' : 'bg-yellow-500 text-black shadow-yellow-900/40 border border-yellow-400/20'
            }`}
          >
            {cashedOut ? 'Won!' : isCrashed ? 'Crashed' : `Cash Out ${(betAmount * multiplier).toFixed(0)}`}
          </button>
        )}
      </div>

      <div className="flex justify-between items-center px-4">
        <p className="text-[9px] text-gray-600 font-black uppercase tracking-widest">Mode: 30s Cycles</p>
        <div className="flex items-center gap-2">
           <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
           <span className="text-[9px] text-green-500/80 font-black uppercase tracking-widest">Engine Synced</span>
        </div>
      </div>
    </div>
  );
};

export default AviatorGame;

import React, { useState, useEffect } from 'react';

const CricketGame: React.FC<{balance: number, onUpdateBalance: (a: number)=>void}> = ({balance, onUpdateBalance}) => {
  const [bet, setBet] = useState(10);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isDrawPhase, setIsDrawPhase] = useState(false);
  const [lastRun, setLastRun] = useState<number | null>(null);
  const [currentPeriod, setCurrentPeriod] = useState("");
  const [myPrediction, setMyPrediction] = useState<number | null>(null);
  const [myBetAmount, setMyBetAmount] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const bettingTime = 20000;
      const period = Math.floor(now / periodDuration).toString();

      setCurrentPeriod(period);

      if (cycleTime < bettingTime) {
        setIsDrawPhase(false);
        setTimeLeft(Math.ceil((bettingTime - cycleTime) / 1000));
      } else {
        if (!isDrawPhase) {
          // Process Draw logic exactly once per cycle at transition
          let hash = 0;
          const seed = period + "cricket_v1";
          for (let i = 0; i < seed.length; i++) {
            hash = ((hash << 5) - hash) + seed.charCodeAt(i);
            hash |= 0;
          }
          const actualRun = [0, 1, 2, 4, 6][Math.abs(hash) % 5];
          setLastRun(actualRun);

          if (myPrediction !== null) {
            if (myPrediction === actualRun) {
              const mult = actualRun === 6 ? 6 : actualRun === 4 ? 4 : 2;
              onUpdateBalance(myBetAmount * mult);
              alert(`Boundary! You predicted ${actualRun} runs. Won 🪙 ${myBetAmount * mult}`);
            }
            setMyPrediction(null);
            setMyBetAmount(0);
          }
        }
        setIsDrawPhase(true);
        setTimeLeft(Math.ceil((periodDuration - cycleTime) / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [isDrawPhase, myPrediction, myBetAmount]);

  const placePrediction = (predict: number) => {
    if (!isDrawPhase && balance >= bet && myPrediction === null) {
      onUpdateBalance(-bet);
      setMyPrediction(predict);
      setMyBetAmount(bet);
    }
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="h-56 bg-gradient-to-br from-green-900 via-emerald-950 to-[#0a0c10] rounded-[2rem] border border-green-500/20 flex flex-col items-center justify-center relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 left-0 w-full h-1 bg-green-500/30"></div>
        <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-green-500/5 blur-3xl rounded-full"></div>

        {isDrawPhase ? (
          <div className="text-center z-10 animate-in zoom-in duration-500">
            <span className="text-7xl drop-shadow-[0_0_15px_rgba(34,197,94,0.3)]">🏏</span>
            <p className="text-[10px] font-black uppercase text-green-400 mt-4 tracking-[0.3em]">Ball in Play...</p>
            <p className="text-4xl font-black font-orbitron text-white mt-2">{lastRun} Runs</p>
          </div>
        ) : (
          <div className="text-center z-10">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-[0.3em] mb-2">Next Ball Starts In</p>
            <p className="text-6xl font-black font-orbitron text-white">{timeLeft}s</p>
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-6 shadow-2xl">
        <div className="text-center">
           <p className="text-[10px] text-gray-500 uppercase font-black tracking-widest mb-4">Select Next Ball Outcome</p>
           <div className="grid grid-cols-5 gap-2">
             {[0, 1, 2, 4, 6].map(run => (
               <button 
                 key={run} 
                 disabled={isDrawPhase || myPrediction !== null}
                 onClick={() => placePrediction(run)}
                 className={`aspect-square rounded-2xl font-black text-xl transition-all border flex items-center justify-center ${
                   myPrediction === run 
                    ? 'bg-green-600 border-green-400 scale-110 shadow-lg' 
                    : 'bg-white/5 border-white/5 text-gray-500 hover:text-white hover:border-white/20'
                 }`}
               >
                 {run}
               </button>
             ))}
           </div>
        </div>

        <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
          <button onClick={() => setBet(Math.max(10, bet-10))} className="w-10 h-10 bg-white/5 rounded-xl font-black text-lg active:scale-90 transition-transform">-</button>
          <div className="text-center">
            <p className="text-[8px] text-gray-600 font-black uppercase mb-0.5">Bet Amount</p>
            <p className="text-lg font-black font-orbitron text-yellow-500">🪙 {bet}</p>
          </div>
          <button onClick={() => setBet(bet+10)} className="w-10 h-10 bg-white/5 rounded-xl font-black text-lg active:scale-90 transition-transform">+</button>
        </div>

        {myPrediction !== null && (
          <div className="text-center py-2 bg-blue-500/10 rounded-xl border border-blue-500/20 animate-pulse">
            <p className="text-[9px] font-black uppercase text-blue-400 tracking-widest">Bet Locked: {myPrediction} Runs</p>
          </div>
        )}
      </div>

      <p className="text-center text-[8px] text-gray-600 font-black uppercase tracking-[0.3em]">Official Cricket Global Sync v2.1</p>
    </div>
  );
};

export default CricketGame;

import React, { useState, useEffect } from 'react';

interface MinesGameProps {
  balance: number;
  onUpdateBalance: (amount: number) => void;
}

const MinesGame: React.FC<MinesGameProps> = ({ balance, onUpdateBalance }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [period, setPeriod] = useState("");
  const [mines, setMines] = useState<number[]>([]);
  const [revealed, setRevealed] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [mineCount, setMineCount] = useState(3);

  // Sync Period Logic
  useEffect(() => {
    const updatePeriod = () => {
      const p = Math.floor(Date.now() / 60000).toString(); // 1 minute period
      setPeriod(p);
    };
    updatePeriod();
    const interval = setInterval(updatePeriod, 1000);
    return () => clearInterval(interval);
  }, []);

  const startGame = () => {
    if (balance < bet) return;
    onUpdateBalance(-bet);

    // Deterministic Board based on Period + mineCount
    const newMines: number[] = [];
    let salt = 0;
    while (newMines.length < mineCount) {
      let hash = 0;
      const seed = period + mineCount + salt + "mines_v1";
      for (let i = 0; i < seed.length; i++) {
        hash = ((hash << 5) - hash) + seed.charCodeAt(i);
        hash |= 0;
      }
      const minePos = Math.abs(hash) % 25;
      if (!newMines.includes(minePos)) newMines.push(minePos);
      salt++;
    }

    setMines(newMines);
    setRevealed([]);
    setGameOver(false);
    setIsPlaying(true);
  };

  const handleTile = (idx: number) => {
    if (!isPlaying || revealed.includes(idx) || gameOver) return;

    if (mines.includes(idx)) {
      setGameOver(true);
      setIsPlaying(false);
    } else {
      setRevealed(prev => [...prev, idx]);
    }
  };

  const cashOut = () => {
    if (!isPlaying) return;
    const multiplier = 1 + (revealed.length * (0.2 + (mineCount * 0.1)));
    const win = bet * multiplier;
    onUpdateBalance(win);
    setIsPlaying(false);
    alert(`Cashed out! Won 🪙 ${win.toFixed(0)}`);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-4">
         <div>
            <p className="text-[9px] text-gray-500 font-black uppercase">Current Board Seed</p>
            <p className="text-xs font-mono font-black text-blue-400">#P-{period}</p>
         </div>
         <div className="bg-blue-600/10 px-3 py-1 rounded-full border border-blue-500/20">
            <span className="text-[9px] font-black uppercase text-blue-500">Board Global Synced</span>
         </div>
      </div>

      <div className="grid grid-cols-5 gap-2 bg-[#0a0c10] p-4 rounded-[2.5rem] border border-white/5 shadow-2xl">
        {Array(25).fill(null).map((_, i) => (
          <button 
            key={i} 
            onClick={() => handleTile(i)}
            className={`aspect-square rounded-2xl transition-all duration-300 flex items-center justify-center text-xl active:scale-90 ${
              revealed.includes(i) ? 'bg-gradient-to-br from-green-500 to-green-700 shadow-lg shadow-green-900/40' : 
              gameOver && mines.includes(i) ? 'bg-gradient-to-br from-red-600 to-red-800 animate-shake' : 
              'bg-[#1e2330] border border-white/5 hover:bg-white/5'
            }`}
          >
            {revealed.includes(i) ? '💎' : gameOver && mines.includes(i) ? '💣' : ''}
          </button>
        ))}
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-6 shadow-2xl">
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-black/40 p-4 rounded-2xl border border-white/5">
            <p className="text-[9px] text-gray-500 uppercase font-black mb-1">Bet Amount</p>
            <p className="text-lg font-black font-orbitron text-yellow-500">🪙 {bet}</p>
          </div>
          <div className="bg-black/40 p-4 rounded-2xl border border-white/5">
            <p className="text-[9px] text-gray-500 uppercase font-black mb-1">Mines Count</p>
            <select 
              disabled={isPlaying}
              value={mineCount} 
              onChange={(e) => setMineCount(Number(e.target.value))} 
              className="bg-transparent text-lg font-black font-orbitron text-white outline-none w-full"
            >
              {[1, 3, 5, 10, 20].map(m => <option key={m} value={m} className="bg-[#1e2330]">{m}</option>)}
            </select>
          </div>
        </div>

        {isPlaying ? (
          <button onClick={cashOut} className="w-full py-5 bg-gradient-to-r from-yellow-600 to-yellow-500 text-black rounded-3xl font-black text-lg uppercase shadow-2xl shadow-yellow-900/40 active:scale-95 transition-all">
            Cash Out 🪙 {(bet * (1 + revealed.length * (0.2 + (mineCount * 0.1)))).toFixed(0)}
          </button>
        ) : (
          <button onClick={startGame} className="w-full py-5 bg-gradient-to-r from-blue-600 to-blue-500 text-white rounded-3xl font-black text-lg uppercase shadow-2xl shadow-blue-900/40 active:scale-95 transition-all">
            Start Global Game
          </button>
        )}
      </div>

      <p className="text-center text-[8px] text-gray-600 font-black uppercase tracking-widest leading-relaxed">
        Boards refresh every 60 seconds. <br/>
        All players on Period #P-{period} play on the identical board layout.
      </p>
    </div>
  );
};

export default MinesGame;

import React, { useState, useEffect } from 'react';

const VortexGame: React.FC<{balance: number, onUpdateBalance: (a: number)=>void}> = ({balance, onUpdateBalance}) => {
  const [timeLeft, setTimeLeft] = useState(0);
  const [isSpinning, setIsSpinning] = useState(false);
  const [angle, setAngle] = useState(0);
  const [period, setPeriod] = useState("");
  const [myBet, setMyBet] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const spinTime = 25000;
      const currentPeriod = Math.floor(now / periodDuration).toString();

      setPeriod(currentPeriod);

      if (cycleTime < spinTime) {
        setIsSpinning(false);
        setTimeLeft(Math.ceil((spinTime - cycleTime) / 1000));
        if (cycleTime < 1000) setMyBet(false);
      } else {
        if (!isSpinning) {
          // Trigger sync spin
          let hash = 0;
          const seed = currentPeriod + "vortex_v1";
          for (let i = 0; i < seed.length; i++) {
            hash = ((hash << 5) - hash) + seed.charCodeAt(i);
            hash |= 0;
          }
          const winAngle = (Math.abs(hash) % 360) + (360 * 10);
          setAngle(prev => prev + winAngle);

          const result = Math.abs(hash) % 10;
          if (myBet) {
            if (result > 7) {
              onUpdateBalance(10 * (result/2));
              alert(`Vortex Shift! Won 🪙 ${(10 * (result/2)).toFixed(0)}`);
            }
          }
        }
        setIsSpinning(true);
        setTimeLeft(Math.ceil((periodDuration - cycleTime) / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [isSpinning, myBet]);

  const initiateShift = () => {
    if (!isSpinning && !myBet && balance >= 10) {
      onUpdateBalance(-10);
      setMyBet(true);
    }
  };

  return (
    <div className="p-4 space-y-8 flex flex-col items-center animate-in fade-in duration-500">
      <div className="text-center">
         <p className="text-[10px] text-purple-500 font-black uppercase tracking-[0.3em] mb-1">Vortex Cycle</p>
         <p className="text-xl font-black font-orbitron"># {period}</p>
      </div>

      <div 
        className="w-64 h-64 rounded-full border-[12px] border-purple-500/10 flex items-center justify-center relative shadow-[0_0_80px_rgba(168,85,247,0.15)] overflow-hidden"
      >
        <div className="absolute inset-0 bg-gradient-to-tr from-purple-900/20 via-transparent to-blue-900/20"></div>
        <div 
           className="w-full h-full flex items-center justify-center transition-all duration-[4s] cubic-bezier(0.1, 0, 0.1, 1)"
           style={{ transform: `rotate(${angle}deg)` }}
        >
           <span className="text-7xl drop-shadow-[0_0_20px_rgba(168,85,247,0.5)]">🌀</span>
        </div>
        <div className="absolute -top-1 left-1/2 -translate-x-1/2 w-4 h-8 bg-white rounded-full shadow-lg z-20"></div>
      </div>

      <div className="bg-[#1e2330] p-8 rounded-[3rem] border border-white/5 w-full text-center space-y-6 shadow-2xl">
        <div className="flex justify-between items-center mb-2">
           <div className="text-left">
              <p className="text-[9px] text-gray-500 font-black uppercase">Current Cost</p>
              <p className="text-lg font-black font-orbitron">🪙 10</p>
           </div>
           <div className="text-right">
              <p className="text-[9px] text-gray-500 font-black uppercase">Next Shift</p>
              <p className="text-lg font-black font-orbitron text-purple-500">{timeLeft}s</p>
           </div>
        </div>

        <button 
          onClick={initiateShift} 
          disabled={isSpinning || myBet}
          className={`w-full py-6 rounded-3xl font-black text-xl uppercase shadow-2xl transition-all active:scale-95 ${
            isSpinning || myBet 
              ? 'bg-gray-800 text-gray-500 border border-white/5' 
              : 'bg-gradient-to-r from-purple-600 to-indigo-600 text-white shadow-purple-900/40 border border-purple-400/20'
          }`}
        >
          {myBet ? 'Bet Locked' : isSpinning ? 'Shifting...' : 'Initiate Shift'}
        </button>

        <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest">Global Vortex Engine - All results synchronized</p>
      </div>
    </div>
  );
};

export default VortexGame;

import React, { useState, useEffect } from 'react';

const ChickenGame: React.FC<{balance: number, onUpdateBalance: (a: number)=>void}> = ({balance, onUpdateBalance}) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [period, setPeriod] = useState("");
  const [pos, setPos] = useState({ x: 2, y: 4 }); // Start middle-bottom
  const [obstacles, setObstacles] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [won, setWon] = useState(false);

  // Sync Period Logic (30s cycles)
  useEffect(() => {
    const update = () => {
      const p = Math.floor(Date.now() / 30000).toString();
      if (p !== period) {
        setPeriod(p);
        resetGame();
      }
    };
    update();
    const interval = setInterval(update, 1000);
    return () => clearInterval(interval);
  }, [period]);

  const resetGame = () => {
    setIsPlaying(false);
    setGameOver(false);
    setWon(false);
    setPos({ x: 2, y: 4 });
    // Deterministic obstacles for this period
    const newObstacles: number[] = [];
    let hash = 0;
    const seed = period + "chicken_v2";
    for (let i = 0; i < seed.length; i++) {
      hash = ((hash << 5) - hash) + seed.charCodeAt(i);
      hash |= 0;
    }
    // Generate 6 random obstacle indices (out of 25)
    for (let i = 0; i < 6; i++) {
      const obs = Math.abs(hash + i * 7) % 25;
      if (obs !== 22) newObstacles.push(obs); // Don't block start
    }
    setObstacles(newObstacles);
  };

  const startGame = () => {
    if (balance < bet) return;
    onUpdateBalance(-bet);
    setIsPlaying(true);
    setGameOver(false);
    setWon(false);
    setPos({ x: 2, y: 4 });
  };

  const move = (dx: number, dy: number) => {
    if (!isPlaying || gameOver || won) return;
    const newX = Math.max(0, Math.min(4, pos.x + dx));
    const newY = Math.max(0, Math.min(4, pos.y + dy));
    const idx = newY * 5 + newX;

    if (obstacles.includes(idx)) {
      setGameOver(true);
      setIsPlaying(false);
    } else {
      setPos({ x: newX, y: newY });
      if (newY === 0) {
        setWon(true);
        setIsPlaying(false);
        const win = bet * 5;
        onUpdateBalance(win);
      }
    }
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-4">
        <div>
          <p className="text-[9px] text-gray-500 font-black uppercase">Sync Period</p>
          <p className="text-xs font-mono font-black text-orange-400">#CH-{period.slice(-4)}</p>
        </div>
        <div className="bg-orange-600/10 px-3 py-1 rounded-full border border-orange-500/20">
          <span className="text-[9px] font-black uppercase text-orange-500">Global Path Synced</span>
        </div>
      </div>

      <div className="grid grid-cols-5 gap-1.5 bg-[#0a0c10] p-3 rounded-[2rem] border border-white/5 shadow-2xl relative">
        {Array(25).fill(null).map((_, i) => {
          const x = i % 5;
          const y = Math.floor(i / 5);
          const isPlayer = pos.x === x && pos.y === y;
          const isObs = obstacles.includes(i) && (gameOver || won);
          const isTarget = y === 0;

          return (
            <div 
              key={i} 
              className={`aspect-square rounded-xl transition-all duration-300 flex items-center justify-center text-xl relative ${
                isTarget ? 'bg-green-500/5 border border-green-500/10' : 'bg-[#1e2330] border border-white/5'
              } ${isObs ? 'bg-red-500/20' : ''}`}
            >
              {isPlayer && <span className="z-10 animate-bounce">🍗</span>}
              {isObs && <span>🔥</span>}
              {isTarget && !isPlayer && <span className="opacity-20 text-xs font-bold text-green-500">WIN</span>}
              {y === 4 && x === 2 && !isPlayer && <span className="opacity-10 text-[8px] font-bold">START</span>}
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-3 gap-2 px-10">
        <div />
        <button onClick={() => move(0, -1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30">▲</button>
        <div />
        <button onClick={() => move(-1, 0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30">◀</button>
        <button onClick={() => move(0, 1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30">▼</button>
        <button onClick={() => move(1, 0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30">▶</button>
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-4 shadow-2xl">
        <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
           <button onClick={() => setBet(Math.max(10, bet - 10))} className="w-10 h-10 bg-white/5 rounded-xl font-black">-</button>
           <div className="text-center">
              <p className="text-[9px] text-gray-500 font-bold uppercase">Bet Amount</p>
              <span className="text-lg font-black font-orbitron text-yellow-500">🪙 {bet}</span>
           </div>
           <button onClick={() => setBet(bet + 10)} className="w-10 h-10 bg-white/5 rounded-xl font-black">+</button>
        </div>

        {!isPlaying ? (
          <button 
            onClick={startGame}
            className="w-full py-5 bg-gradient-to-r from-orange-600 to-orange-500 text-white rounded-3xl font-black text-lg uppercase shadow-2xl shadow-orange-900/40 active:scale-95 transition-all"
          >
            Start Journey
          </button>
        ) : (
          <div className="text-center py-4 bg-orange-500/10 rounded-2xl border border-orange-500/20">
             <p className="text-xs font-black text-orange-400 uppercase tracking-widest animate-pulse">Reach Top Row to Win 5X!</p>
          </div>
        )}
      </div>

      {gameOver && <p className="text-center text-red-500 font-black uppercase text-xs animate-bounce">Chicken Burned! Try Again</p>}
      {won && <p className="text-center text-green-500 font-black uppercase text-xs animate-bounce">Level Clear! 5X Payout Claimed</p>}

      <p className="text-center text-[8px] text-gray-600 font-black uppercase tracking-widest leading-relaxed">
        Obstacles refresh every 30 seconds. <br/>
        All players see the exact same road during the period.
      </p>
    </div>
  );
};

