import React, { useState, useEffect } from 'react';

const ChickenGame: React.FC<{balance: number, onUpdateBalance: (a: number)=>void}> = ({balance, onUpdateBalance}) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [period, setPeriod] = useState("");
  const [pos, setPos] = useState({ x: 2, y: 4 }); // Start middle-bottom
  const [obstacles, setObstacles] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [won, setWon] = useState(false);

  // Sync Period Logic (30s cycles)
  useEffect(() => {
    const update = () => {
      const p = Math.floor(Date.now() / 30000).toString();
      if (p !== period) {
        setPeriod(p);
        resetGame(p);
      }
    };
    update();
    const interval = setInterval(update, 1000);
    return () => clearInterval(interval);
  }, [period]);

  const resetGame = (p: string) => {
    setIsPlaying(false);
    setGameOver(false);
    setWon(false);
    setPos({ x: 2, y: 4 });

    // Deterministic obstacles for this period
    const newObstacles: number[] = [];
    let hash = 0;
    const seed = p + "chicken_v2_final";
    for (let i = 0; i < seed.length; i++) {
      hash = ((hash << 5) - hash) + seed.charCodeAt(i);
      hash |= 0;
    }

    // Generate 7 deterministic obstacles
    for (let i = 0; i < 7; i++) {
      const obs = Math.abs(hash + i * 13) % 25;
      if (obs !== 22 && !newObstacles.includes(obs)) newObstacles.push(obs); 
    }
    setObstacles(newObstacles);
  };

  const startGame = () => {
    if (balance < bet) return;
    onUpdateBalance(-bet);
    setIsPlaying(true);
    setGameOver(false);
    setWon(false);
    setPos({ x: 2, y: 4 });
  };

  const move = (dx: number, dy: number) => {
    if (!isPlaying || gameOver || won) return;
    const newX = Math.max(0, Math.min(4, pos.x + dx));
    const newY = Math.max(0, Math.min(4, pos.y + dy));
    const idx = newY * 5 + newX;

    if (obstacles.includes(idx)) {
      setGameOver(true);
      setIsPlaying(false);
    } else {
      setPos({ x: newX, y: newY });
      if (newY === 0) {
        setWon(true);
        setIsPlaying(false);
        const win = bet * 5;
        onUpdateBalance(win);
      }
    }
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-700">
      <div className="flex justify-between items-center px-4">
        <div>
          <p className="text-[9px] text-gray-500 font-black uppercase">Draw Period</p>
          <p className="text-sm font-mono font-black text-orange-500 tracking-tighter">#CH-{period.slice(-4)}</p>
        </div>
        <div className="bg-orange-600/10 px-4 py-1.5 rounded-full border border-orange-500/20 flex items-center gap-2">
          <span className="w-1.5 h-1.5 bg-orange-500 rounded-full animate-pulse"></span>
          <span className="text-[9px] font-black uppercase text-orange-500 tracking-widest">Path Synced</span>
        </div>
      </div>

      <div className="grid grid-cols-5 gap-2 bg-[#0a0c10] p-4 rounded-[2.5rem] border border-white/5 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-orange-500/5 via-transparent to-transparent"></div>
        {Array(25).fill(null).map((_, i) => {
          const x = i % 5;
          const y = Math.floor(i / 5);
          const isPlayer = pos.x === x && pos.y === y;
          const isObs = obstacles.includes(i) && (gameOver || won);
          const isTarget = y === 0;

          return (
            <div 
              key={i} 
              className={`aspect-square rounded-2xl transition-all duration-300 flex items-center justify-center text-2xl relative border ${
                isTarget ? 'bg-green-500/5 border-green-500/20' : 'bg-[#1e2330] border-white/5'
              } ${isObs ? 'bg-red-500/30 border-red-500/40 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : ''} ${isPlayer ? 'z-20' : ''}`}
            >
              {isPlayer && <span className="animate-bounce drop-shadow-[0_0_10px_rgba(0,0,0,0.5)]">🍗</span>}
              {isObs && <span className="animate-pulse">🔥</span>}
              {isTarget && !isPlayer && !isObs && <span className="opacity-10 text-[6px] font-black text-green-500 tracking-widest">GOAL</span>}
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-3 gap-3 px-10">
        <div />
        <button onClick={() => move(0, -1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30 shadow-lg text-xl">▲</button>
        <div />
        <button onClick={() => move(-1, 0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30 shadow-lg text-xl">◀</button>
        <button onClick={() => move(0, 1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30 shadow-lg text-xl">▼</button>
        <button onClick={() => move(1, 0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-2xl flex items-center justify-center border border-white/10 active:scale-90 disabled:opacity-30 shadow-lg text-xl">▶</button>
      </div>

      <div className="bg-[#1e2330] rounded-[3rem] p-6 border border-white/5 space-y-4 shadow-2xl relative overflow-hidden">
        <div className="absolute bottom-0 right-0 w-32 h-32 bg-orange-500/5 blur-3xl -mr-16 -mb-16"></div>
        <div className="flex justify-between items-center bg-black/40 p-5 rounded-3xl border border-white/5">
           <button onClick={() => setBet(Math.max(10, bet - 10))} className="w-12 h-12 bg-white/5 rounded-2xl font-black text-xl active:scale-90">-</button>
           <div className="text-center">
              <p className="text-[10px] text-gray-500 font-black uppercase mb-1">Bet Amount</p>
              <span className="text-xl font-black font-orbitron text-yellow-500">🪙 {bet}</span>
           </div>
           <button onClick={() => setBet(bet + 10)} className="w-12 h-12 bg-white/5 rounded-2xl font-black text-xl active:scale-90">+</button>
        </div>

        {!isPlaying ? (
          <button 
            onClick={startGame}
            className="w-full py-6 bg-gradient-to-r from-orange-600 to-orange-500 text-white rounded-[2rem] font-black text-lg uppercase shadow-2xl shadow-orange-900/40 active:scale-95 transition-all border border-orange-400/20"
          >
            Start Global Journey
          </button>
        ) : (
          <div className="text-center py-5 bg-orange-500/10 rounded-3xl border border-orange-500/20 animate-pulse">
             <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest">Navigate Carefully...</p>
          </div>
        )}
      </div>

      {gameOver && <p className="text-center text-red-500 font-black uppercase text-xs tracking-widest animate-shake">CRASHED! REGENERATING ROAD...</p>}
      {won && <p className="text-center text-green-500 font-black uppercase text-xs tracking-widest animate-bounce">VICTORY! YOU REACHED THE GOAL</p>}

      <p className="text-center text-[9px] text-gray-600 font-black uppercase tracking-[0.2em] leading-relaxed">
        Map refreshes in 30s. Synchronized result for all players.
      </p>
    </div>
  );
};

